import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { writeIdentityDossierStore, readIdentityDossierStore } from './lib/people-identity-dossier-store.mjs';
const revision = '1'.repeat(40), version = `sha256:${'2'.repeat(64)}`;
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'identity-dossier-test-')); t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  const directory = path.join(root, 'generation'); const index = {
    dossiers: new Map([['per_one', { id: 'per_one', version, names: ['One'], localPeople: ['fixture:001:p001'] }]]),
    postings: new Map([['en:one', { ids: ['per_one'], total: 1, fingerprint: version }]]),
    englishUnknownPostings: new Map(), localPersonMap: new Map([['fixture:001:p001', 'per_one']]), memberVersions: new Map([['fixture:001:p001', version]]),
    canonicalByKnownId: new Map([['per_one', 'per_one']]), chapters: new Map([['fixture:001', new Map([['per_one', ['fixture:001:p001']]])]]),
  }; return { root, directory, index };
}
test('persistent dossiers support fingerprinted direct lookup and explicit close', async t => {
  const f = fixture(t), manifest = writeIdentityDossierStore(f.directory, f.index, { revision });
  assert.equal(manifest.dossierCount, 1); assert.equal(manifest.publicationApproval, false);
  const reader = await readIdentityDossierStore(f.directory, new Map()); t.after(() => reader.close());
  assert.deepEqual(reader.dossiers.get('per_one'), f.index.dossiers.get('per_one'));
  assert.deepEqual(reader.chapters.get('fixture:001').get('per_one'), ['fixture:001:p001']);
  assert.equal(reader.dossiers.get('missing'), undefined); reader.close(); assert.throws(() => reader.dossiers.get('per_one'), /closed/);
});
test('an interrupted generation has no usable manifest', async t => {
  const f = fixture(t); fs.mkdirSync(f.directory); fs.writeFileSync(path.join(f.directory, 'dossiers.jsonl'), '{}\n');
  await assert.rejects(readIdentityDossierStore(f.directory, new Map()), /ENOENT/);
});
test('modified dossier bytes fail before evidence can be read', async t => {
  const f = fixture(t); writeIdentityDossierStore(f.directory, f.index, { revision });
  const file = path.join(f.directory, 'dossiers.jsonl'), b = fs.readFileSync(file, 'utf8'); fs.writeFileSync(file, b.replace('One', 'Two'));
  const reader = await readIdentityDossierStore(f.directory, new Map()); t.after(() => reader.close());
  assert.throws(() => reader.dossiers.get('per_one'), /bytes changed/);
});
test('changed registry metadata fails rather than silently rebuilding a different index', async t => {
  const f = fixture(t); writeIdentityDossierStore(f.directory, f.index, { revision });
  const file = path.join(f.directory, 'index.jsonl'); fs.appendFileSync(file, '\n');
  await assert.rejects(readIdentityDossierStore(f.directory, new Map()), /Truncated/);
});
test('an existing immutable generation is never overwritten', t => {
  const f = fixture(t); writeIdentityDossierStore(f.directory, f.index, { revision }); const file = path.join(f.directory, 'manifest.json');
  const before = fs.readFileSync(file); assert.throws(() => writeIdentityDossierStore(f.directory, f.index, { revision }), /EEXIST/);
  assert.deepEqual(fs.readFileSync(file), before);
});
test('oversized evidence fails with its partial generation preserved and unpublished', t => {
  const f = fixture(t); f.index.dossiers.get('per_one').names = ['x'.repeat(17 * 1024 * 1024)];
  assert.throws(() => writeIdentityDossierStore(f.directory, f.index, { revision }), /storage bound/);
  assert.equal(fs.existsSync(path.join(f.directory, 'manifest.json')), false);
  assert.equal(fs.existsSync(path.join(f.directory, 'dossiers.jsonl')), true);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { localNameKeys } from './lib/people-resolution.mjs';
import { buildIdentityDossierIndex, planChapterIdentityReview, validateRetainedDossierReview } from './lib/people-identity-dossiers.mjs';

const inputs = Object.fromEntries(['source', 'extraction', 'editorial', 'dateAudit'].map((key, i) => [key, `sha256:${String(i + 1).repeat(64)}`]));
const limits = { maxDossiersPerCase: 8, maxKeysPerCase: 16, maxPostingReadsPerKey: 8 };
const keyReader = person => person.keys;
function person(id, name = '王偉', english = 'Wang Wei') {
  const [book, chapter] = id.split(':'); const claimId = `${book}:${chapter}:c${id.split(':p')[1]}`;
  return { localId: id, promptVersion: 7, preferredNameSuggestion: { zh: name, en: english }, keys: [
    { key: `zh:${name}`, language: 'zh', value: name, kinds: ['personal'], blocking: true, sources: [claimId] },
    { key: `en:${english.toLowerCase()}`, language: 'en', value: english, kinds: ['personal'], blocking: true, sources: [claimId] },
  ], claims: [{ id: claimId, subject: id, predicate: 'name', value: { zh: name, en: english, kind: 'personal-name' },
    certainty: 'explicit', evidence: [`${book}:${chapter}:s0001`] }] };
}
function fixture(size = 20) {
  const records = new Map(), clusters = [];
  for (let i = 0; i < size; i += 1) {
    const id = `fixture:${i < 3 ? '001' : '002'}:p${String(i + 1).padStart(5, '0')}`;
    records.set(id, person(id)); clusters.push({ canonicalPersonId: `per_${String(i).padStart(6, '0')}`, localPeople: [id], retiredIds: [] });
  }
  const index = buildIdentityDossierIndex(records, clusters, keyReader);
  const plan = planChapterIdentityReview(index, { book: 'fixture', chapter: '001' }, inputs, limits);
  const sourceUnits = new Map([['fixture:001:s0001', '王偉字仲明。'], ['fixture:002:s0001', '王偉字仲明。']]);
  const report = { schemaVersion: 1, planFingerprint: plan.fingerprint, reviewer: { agentId: 'independent', name: 'Independent source reviewer' },
    reviews: plan.cases.map(item => ({ caseId: item.id, canonicalPersonId: item.canonicalPersonId, verdict: 'approve', membershipReviewed: true, membershipFingerprint: item.canonicalMembership.fingerprint, ambiguityReviewed: true,
      unresolvedIdentity: true, reason: 'Primary Chinese identifies this local person; cross-chapter equivalence remains unestablished, so retain the accepted assignment.',
      sourceWitnesses: item.localPeople.map(localId => ({ localId, book: 'fixture', chapter: '001', unitId: 's0001', quote: '王偉' })) })) };
  return { records, clusters, index, plan, report, sourceUnits };
}
const validate = f => validateRetainedDossierReview(f.index, f.plan, f.report, f.sourceUnits, 'independent', ['extractor', 'host-author'], inputs, keyReader);

test('one case per canonical person, with accepted local records kept together', () => {
  const f = fixture(); const merged = { canonicalPersonId: f.clusters[0].canonicalPersonId,
    localPeople: [...f.clusters[0].localPeople, ...f.clusters[1].localPeople], retiredIds: [f.clusters[1].canonicalPersonId] };
  const index = buildIdentityDossierIndex(f.records, [merged, ...f.clusters.slice(2)], keyReader);
  const plan = planChapterIdentityReview(index, f.plan.scope, inputs, limits);
  assert.equal(plan.cases.length, 2); assert.equal(plan.metrics.targetLocalPeople, 3);
  assert.equal(plan.cases[0].localPeople.length, 2); assert.equal(plan.metrics.generatedPairs, 0);
});

test('reviewed ambiguity retains separate records without granting merges or publication', () => {
  const f = fixture(), certificate = validate(f);
  assert.equal(certificate.retained.length, 3); assert.equal(certificate.ambiguity.length, 3);
  assert.equal(certificate.grantsNewMerges, false); assert.equal(certificate.grantsNewSeparations, false);
  assert.equal(certificate.publicationApproval, false); assert.equal(f.index.dossiers.size, 20);
});

test('overflow is explicit and cannot be relabelled as identity certainty', () => {
  const f = fixture(); assert.ok(f.plan.cases.every(item => item.retrieval.overflow));
  f.report.reviews[0].unresolvedIdentity = false;
  assert.throws(() => validate(f), /ambiguity cannot become/);
});

test('an incomplete or self-authored review cannot authorize chapter completion', () => {
  const f = fixture(); f.report.reviews.pop(); assert.throws(() => validate(f), /Missing or duplicate/);
  const g = fixture(); g.report.reviewer.agentId = 'host-author';
  assert.throws(() => validateRetainedDossierReview(g.index, g.plan, g.report, g.sourceUnits, 'host-author', ['host-author'], inputs, keyReader), /independent reviewer/);
});

test('stale chapter inputs, altered case assignments and invented witnesses fail', () => {
  const f = fixture(); assert.throws(() => validateRetainedDossierReview(f.index, f.plan, f.report, f.sourceUnits,
    'independent', ['host-author'], { ...inputs, source: `sha256:${'f'.repeat(64)}` }, keyReader), /inputs changed/);
  const g = fixture(); g.report.reviews[0].canonicalPersonId = 'per_invented'; assert.throws(() => validate(g), /assignment or source-person/);
  const h = fixture(); h.report.reviews[0].sourceWitnesses[0].quote = '不存在'; assert.throws(() => validate(h), /current primary source/);
});

test('a certificate cannot smuggle a new merge through extra fields', () => {
  const f = fixture(); f.report.reviews[0].decision = 'merge'; assert.throws(() => validate(f), /Unexpected person review fields/);
});

test('held cases remain blocked and every local person needs primary source evidence', () => {
  const f = fixture(); f.report.reviews[0].verdict = 'hold'; assert.throws(() => validate(f), /held or unknown/);
  const g = fixture(); g.report.reviews[0].sourceWitnesses = []; assert.throws(() => validate(g), /witnesses are required/);
});

test('accepted membership growth does not reopen unchanged chapter source identities', () => {
  const f = fixture(); const merged = { canonicalPersonId: f.clusters[3].canonicalPersonId,
    localPeople: [...f.clusters[0].localPeople, ...f.clusters[3].localPeople], retiredIds: [f.clusters[0].canonicalPersonId] };
  f.index = buildIdentityDossierIndex(f.records, [merged, f.clusters[1], f.clusters[2], ...f.clusters.slice(4)], keyReader);
  const certificate = validate(f); assert.equal(certificate.retained[0].canonicalPersonId, merged.canonicalPersonId);
});

test('source-identity edits and newly extracted chapter people require fresh coverage', () => {
  const f = fixture(); const changed = structuredClone(f.records); changed.values().next().value.claims[0].value.zh = '王威';
  f.index = buildIdentityDossierIndex(changed, f.clusters, keyReader); assert.throws(() => validate(f), /source-person evidence changed/);
  const g = fixture(); const id = 'fixture:001:p99999'; g.records.set(id, person(id));
  g.index = buildIdentityDossierIndex(g.records, [...g.clusters, { canonicalPersonId: 'per_added', localPeople: [id], retiredIds: [] }], keyReader);
  assert.throws(() => validate(g), /coverage changed/);
});

test('same-name bucket size never creates a complete comparison graph', () => {
  const samples = [];
  for (const size of [100, 1000, 10000]) {
    const start = performance.now(), f = fixture(size), elapsedMs = performance.now() - start;
    assert.equal(f.plan.metrics.generatedPairs, 0);
    assert.ok(f.plan.metrics.postingIdsVisited <= 3 * 2 * limits.maxPostingReadsPerKey);
    assert.ok(f.plan.cases.every(item => item.candidateDossiers.length <= limits.maxDossiersPerCase));
    assert.ok(f.plan.cases.every(item => item.retrieval.queries.some(query => query.totalDossiers === size && query.omitted)));
    samples.push({ bucketSize: size, chapterPeople: 3, postingIdsVisited: f.plan.metrics.postingIdsVisited,
      candidateDossiers: f.plan.metrics.candidateDossiers, generatedPairs: f.plan.metrics.generatedPairs, elapsedMs: Math.round(elapsedMs) });
  }
  console.log('bounded-identity-scaling ' + JSON.stringify(samples));
});


test('admission bounds cannot be widened by a caller', () => {
  const f = fixture();
  for (const key of Object.keys(limits)) assert.throws(() => planChapterIdentityReview(f.index, f.plan.scope, inputs,
    { ...limits, [key]: limits[key] + 1 }), /hard retrieval limit/);
});

test('an arbitrary Han substring is not a source identity witness', () => {
  const f = fixture(); f.report.reviews[0].sourceWitnesses[0].quote = '字';
  assert.throws(() => validate(f), /current primary source/);
});

test('complete accepted membership and an external primary anchor are required', () => {
  const f = fixture(); const merged = { canonicalPersonId: f.clusters[0].canonicalPersonId,
    localPeople: [...f.clusters[0].localPeople, ...f.clusters[3].localPeople], retiredIds: [f.clusters[3].canonicalPersonId] };
  f.index = buildIdentityDossierIndex(f.records, [merged, f.clusters[1], f.clusters[2], ...f.clusters.slice(4)], keyReader);
  f.plan = planChapterIdentityReview(f.index, f.plan.scope, inputs, limits);
  f.report.planFingerprint = f.plan.fingerprint;
  f.report.reviews = f.plan.cases.map(item => ({ caseId: item.id, canonicalPersonId: item.canonicalPersonId, verdict: 'approve',
    membershipReviewed: true, membershipFingerprint: item.canonicalMembership.fingerprint,
    ambiguityReviewed: true, unresolvedIdentity: true, reason: 'Retain source-backed identity with reviewed cross-chapter uncertainty.',
    sourceWitnesses: item.localPeople.map(localId => ({ localId, book: 'fixture', chapter: '001', unitId: 's0001', quote: '王偉' })) }));
  assert.throws(() => validate(f), /identity-anchor witness/);
  const item = f.plan.cases[0];
  f.report.reviews[0].sourceWitnesses.push({ localId: item.canonicalMembership.anchorLocalId,
    book: 'fixture', chapter: '002', unitId: 's0001', quote: '王偉' });
  assert.equal(validate(f).retained.length, 3);
  f.report.reviews[0].membershipReviewed = false;
  assert.throws(() => validate(f), /canonical membership/);
});

test('small complete candidate buckets still cannot mint separation certainty', () => {
  const f = fixture(4); assert.ok(f.plan.cases.every(item => !item.retrieval.overflow));
  f.report.reviews[0].unresolvedIdentity = false;
  assert.throws(() => validate(f), /ambiguity cannot become/);
});

test('normal native generic-title rules remain active in the dossier index', () => {
  const p = person('fixture:001:p001', '太子', 'Crown Prince'); p.claims[0].value.kind = 'title-name';
  const index = buildIdentityDossierIndex(new Map([[p.localId, p]]),
    [{ canonicalPersonId: 'per_title', localPeople: [p.localId], retiredIds: [] }], localNameKeys);
  assert.equal(index.postings.has('en:crown prince'), false); assert.equal(index.postings.has('zh:太子'), false);
});

test('canonical source Chinese partitions English lookups without a pair graph', () => {
  const a = person('fixture:001:p001', '王偉'), b = person('fixture:002:p002', '王維');
  const index = buildIdentityDossierIndex(new Map([[a.localId, a], [b.localId, b]]),
    [{ canonicalPersonId: 'per_a', localPeople: [a.localId], retiredIds: [] },
      { canonicalPersonId: 'per_b', localPeople: [b.localId], retiredIds: [] }], localNameKeys);
  const plan = planChapterIdentityReview(index, { book: 'fixture', chapter: '001' }, inputs, limits);
  assert.equal(plan.cases[0].candidateDossiers.length, 0);
  assert.equal(plan.cases[0].retrieval.overflow, false); assert.equal(plan.metrics.generatedPairs, 0);
  assert.ok(plan.cases[0].retrieval.queries.some(query => query.mode === 'source-Chinese-partition' && query.fullNamePostingCount === 2));
});


test('primary Chinese witness names preserve the existing approved variant equivalence', () => {
  const f = fixture(1), localId = f.clusters[0].localPeople[0]; f.records.set(localId, person(localId, '張機', 'Zhang Ji'));
  f.index = buildIdentityDossierIndex(f.records, f.clusters, localNameKeys);
  f.plan = planChapterIdentityReview(f.index, f.plan.scope, inputs, limits); const item = f.plan.cases[0];
  f.report.planFingerprint = f.plan.fingerprint; f.report.reviews[0].caseId = item.id;
  f.report.reviews[0].membershipFingerprint = item.canonicalMembership.fingerprint;
  f.report.reviews[0].sourceWitnesses[0].quote = '张机'; f.sourceUnits.set('fixture:001:s0001', '张机在京。');
  const certificate = validateRetainedDossierReview(f.index, f.plan, f.report, f.sourceUnits,
    'independent', ['host-author'], inputs, localNameKeys);
  assert.equal(certificate.retained.length, 1);
});

import { peopleDigest } from './people-identity-seal.mjs';
import { chineseVariantComparisonKey } from './people-chinese-variants.mjs';
import { identityNameKeyState } from './people-resolution.mjs';

export const IDENTITY_REVIEW_LIMITS = Object.freeze({ maxDossiersPerCase: 8, maxKeysPerCase: 16, maxPostingReadsPerKey: 8 });

const digestPattern = /^sha256:[a-f0-9]{64}$/u;
const requireValue = (condition, message) => { if (!condition) throw new Error(message); };
const compare = (a, b) => a.localeCompare(b, 'en');
const hasOnlyKeys = (object, keys) => object && Object.keys(object).sort().join('\0') === [...keys].sort().join('\0');
const normalizeKey = key => key.startsWith('zh:') ? chineseVariantComparisonKey(key) : key;
const identityPredicates = new Set(['name', 'birth', 'death', 'sex', 'role', 'office',
  'native-place', 'family-relationship', 'relationship', 'kinship', 'lineage']);

function memberContract(person, keys) {
  return { localId: person.localId, promptVersion: person.promptVersion, names: keys,
    claims: person.claims.filter(claim => identityPredicates.has(claim.predicate)) };
}

// Matching indexes accepted canonical people. Local records remain provenance,
// never vertices of a new complete comparison graph.
export function buildIdentityDossierIndex(localPeople, clusters, nameKeysForPerson) {
  requireValue(localPeople instanceof Map && Array.isArray(clusters) && typeof nameKeysForPerson === 'function',
    'Validated people, accepted clusters and the normal name-key reader are required');
  const dossiers = new Map(), localPersonMap = new Map(), postings = new Map(), englishUnknownPostings = new Map(), chapters = new Map(), memberVersions = new Map(), canonicalByKnownId = new Map();
  for (const cluster of clusters) {
    requireValue(typeof cluster.canonicalPersonId === 'string' && !dossiers.has(cluster.canonicalPersonId), 'Duplicate/invalid canonical dossier');
    const members = [...cluster.localPeople].sort(compare), names = new Map(), contracts = [], anchors = [];
    for (const knownId of [cluster.canonicalPersonId, ...(cluster.retiredIds ?? [])]) {
      requireValue(!canonicalByKnownId.has(knownId), 'Conflicting accepted canonical lineage');
      canonicalByKnownId.set(knownId, cluster.canonicalPersonId);
    }
    requireValue(members.length > 0 && new Set(members).size === members.length, 'Empty/duplicate canonical membership');
    for (const localId of members) {
      const person = localPeople.get(localId);
      requireValue(person && person.localId === localId && !localPersonMap.has(localId) && Array.isArray(person.claims),
        `Invalid, missing or multiply assigned source member ${localId}`);
      localPersonMap.set(localId, cluster.canonicalPersonId);
      const chapterKey = localId.split(':').slice(0, 2).join(':');
      if (!chapters.has(chapterKey)) chapters.set(chapterKey, new Map());
      const subjects = chapters.get(chapterKey);
      if (!subjects.has(cluster.canonicalPersonId)) subjects.set(cluster.canonicalPersonId, []);
      subjects.get(cluster.canonicalPersonId).push(localId);
      const keys = nameKeysForPerson(person);
      requireValue(Array.isArray(keys), 'Name-key reader did not return an array');
      const contract = memberContract(person, keys);
      contracts.push(contract); memberVersions.set(localId, peopleDigest(contract));
      const state = identityNameKeyState(keys);
      anchors.push({ localId, rank: state.chinese.size ? 2 : keys.some(key => key.language === 'zh' && key.sources.some(source => source !== 'preferred')) ? 1 : 0 });
      for (const name of keys) {
        requireValue(typeof name.key === 'string' && Array.isArray(name.kinds) && typeof name.blocking === 'boolean', 'Invalid source name key');
        const key = normalizeKey(name.key);
        if (!names.has(key)) names.set(key, { key, language: name.language, forms: new Set(), kinds: new Set(), blocking: false, claimRefs: new Set() });
        const entry = names.get(key);
        entry.forms.add(name.value);
        for (const kind of name.kinds) entry.kinds.add(kind);
        for (const source of name.sources ?? []) if (source !== 'preferred') entry.claimRefs.add(source);
        entry.blocking ||= name.blocking;
      }
    }
    const identityNames = [...names.values()].map(name => ({ ...name,
      forms: [...name.forms].sort(compare), kinds: [...name.kinds].sort(compare), claimRefs: [...name.claimRefs].sort(compare),
    })).sort((a, b) => keyPriority(a) - keyPriority(b) || compare(a.key, b.key));
    const keyState = identityNameKeyState(identityNames);
    const dossier = { id: cluster.canonicalPersonId, localPeople: members, names: identityNames,
      identityEvidence: contracts.map(({ localId, claims }) => ({ localId, claims })),
      anchorCandidates: anchors.sort((a, b) => b.rank - a.rank || compare(a.localId, b.localId)).map(anchor => anchor.localId),
      matching: { chineseIdentityKeys: [...keyState.chinese].sort(compare), englishIdentityKeys: [...keyState.english].sort(compare) },
      version: peopleDigest({ canonicalPersonId: cluster.canonicalPersonId, contracts }),
      evidenceContract: 'Version covers normalized source-backed identity claims and names; review certificates separately pin current chapter bytes and exact primary witnesses.' };
    dossiers.set(dossier.id, dossier);
    for (const name of identityNames) if (name.blocking) {
      if (!postings.has(name.key)) postings.set(name.key, []);
      postings.get(name.key).push(dossier.id);
      if (name.language === 'en') {
        if (!englishUnknownPostings.has(name.key)) englishUnknownPostings.set(name.key, []);
        if (!keyState.english.has(name.key) || keyState.chinese.size === 0) englishUnknownPostings.get(name.key).push(dossier.id);
      }
    }
  }
  requireValue(localPersonMap.size === localPeople.size, 'Canonical dossiers do not cover every validated local person');
  for (const map of [postings, englishUnknownPostings]) for (const [key, ids] of map) {
    ids.sort(compare);
    map.set(key, { ids, total: ids.length, fingerprint: peopleDigest({ key, ids }) });
  }
  return { schemaVersion: 1, dossiers, dossierVersions: new Map([...dossiers].map(([id, dossier]) => [id, dossier.version])), postings, englishUnknownPostings, localPersonMap, localPeople, chapters, memberVersions, canonicalByKnownId };
}

const keyPriority = name => name.key.startsWith('zh:') ? 0 : name.key.includes(' ') ? 1 : 2;

export function planChapterIdentityReview(index, scope, inputs, limits) {
  requireValue(/^[a-z0-9_-]+$/u.test(scope?.book ?? '') && /^\d{3}$/u.test(scope?.chapter ?? ''), 'One explicit chapter is required');
  for (const key of ['source', 'extraction', 'editorial', 'dateAudit']) requireValue(digestPattern.test(inputs?.[key] ?? ''), `Missing current ${key} byte fingerprint`);
  for (const key of ['maxDossiersPerCase', 'maxKeysPerCase', 'maxPostingReadsPerKey']) {
    requireValue(Number.isSafeInteger(limits?.[key]) && limits[key] >= 1 && limits[key] <= IDENTITY_REVIEW_LIMITS[key], `Invalid hard retrieval limit ${key}`);
  }
  const subjects = index.chapters.get(`${scope.book}:${scope.chapter}`) ?? new Map();
  requireValue(subjects.size > 0, 'A zero-person chapter cannot prove the nonempty completion path');
  const cases = [], metrics = { cases: subjects.size, targetLocalPeople: 0, postingIdsVisited: 0, candidateDossiers: 0,
    generatedPairs: 0, maxDossiersInCase: 0, overflowCases: 0 };
  for (const [canonicalId, members] of [...subjects].sort(([a], [b]) => compare(a, b))) {
    const dossier = index.dossiers.get(canonicalId), keys = dossier.names.filter(name => name.blocking), englishIdentityKeys = new Set(dossier.matching.englishIdentityKeys);
    const candidates = new Map(), queries = []; let overflow = false;
    for (const [position, name] of keys.entries()) {
      const allPosting = index.postings.get(name.key);
      requireValue(allPosting, `Missing dossier index entry ${name.key}`);
      const partitioned = name.language === 'en' && dossier.matching.chineseIdentityKeys.length > 0 && englishIdentityKeys.has(name.key);
      const posting = partitioned ? index.englishUnknownPostings.get(name.key) : allPosting;
      requireValue(posting, `Missing canonical source-name partition ${name.key}`);
      const selected = position < limits.maxKeysPerCase;
      const readCount = selected ? Math.min(posting.total, limits.maxPostingReadsPerKey) : 0;
      const query = { key: name.key, mode: partitioned ? 'source-Chinese-partition' : 'exact-name',
        fullNamePostingCount: allPosting.total, fullNamePostingFingerprint: allPosting.fingerprint, postingFingerprint: posting.fingerprint, totalDossiers: posting.total,
        postingIdsVisited: readCount, omitted: !selected || posting.total > readCount };
      overflow ||= query.omitted;
      for (let offset = 0; offset < readCount; offset += 1) {
        metrics.postingIdsVisited += 1;
        const id = posting.ids[offset];
        if (id === canonicalId) continue;
        if (!candidates.has(id)) {
          if (candidates.size === limits.maxDossiersPerCase) { overflow = true; continue; }
          const version = index.dossierVersions.get(id);
          requireValue(digestPattern.test(version ?? ''), `Missing indexed dossier version ${id}`);
          candidates.set(id, { id, version, sharedKeys: [] });
        }
        candidates.get(id).sharedKeys.push(name.key);
      }
      queries.push(query);
    }
